mapper.select:
select 
  from builder.adk_builder_design_system_curation
 where project_id = #{projectId} and system_id = #{systemId}

mapper.update:
update builder.adk_builder_design_system_curation
   set content_json = #{contentJson}, version = version + 1,
       updated_at = now(), updated_by = #{updatedBy,jdbcType=VARCHAR}
 where project_id = #{projectId} and system_id = #{systemId}
   and version = #{expectedVersion}
